# generated by tools/ail2py.py from line_histogram_core.ail; edit the .ail until onelang s16
def emit_counts(content: str) -> int:
    counts = {}
    for line in content.splitlines():
        counts[line] = counts.get(line, 0) + 1
    for line in counts:
        print(line, counts[line], sep='\t')
    return len(counts)
